// remen.uz products (data/products.json, generated by scripts/build-data.mjs). Server-only: the full
// file is large, so pages pass slim `ProductCard` lists to client components.
import "server-only";
import productsJson from "@/data/products.json";

export type Product = {
  id: number;
  slug: string;
  name: string;
  sku: string;
  brand: string | null;
  price: number;
  oldPrice: number | null;
  inStock: boolean;
  isNew: boolean;
  isHit: boolean;
  perMeter: boolean;
  img: string | null;
  imgSmall: string | null;
  cats: number[];
  attrs: [string, string][];
  body: string;
};

export type ProductCard = Pick<Product, "id" | "slug" | "name" | "sku" | "brand" | "price" | "perMeter" | "isNew" | "isHit" | "imgSmall">;

export const PRODUCTS = productsJson as Product[];

const bySlug = new Map(PRODUCTS.map((p) => [p.slug, p]));
export const getProduct = (slug: string) => bySlug.get(slug);

export const toCard = ({ id, slug, name, sku, brand, price, perMeter, isNew, isHit, imgSmall }: Product): ProductCard => ({
  id, slug, name, sku, brand, price, perMeter, isNew, isHit, imgSmall,
});

export const productsIn = (catId: number) => PRODUCTS.filter((p) => p.cats.includes(catId));
